/// <reference types="lvyjs/env" />
/// <reference types="alemonjs/env" />

declare module '*.png' {
  const src: string
  export default src
}
declare module '*.scss' {
  const src: string
  export default src
}
declare module '*.css' {
  const src: string
  export default src
}
declare module '*.less' {
  const src: string
  export default src
}
declare module '*.sass' {
  const src: string
  export default src
}
declare module '*.ttf' {
  const url: string
  export default url
}
